{"path":"solutions/t1-digits.res","content":"sheye line <- diwela();
veshim (line <> malwe) {
    sheye i <- 0;
    sheye sign <- "";
    wesosa (line[0] = "-") {
        sign <- "-";
        i <- 1;
    }
    sheye sum <- 0;
    sheye rev <- "";
    wesosa (i = louwo(line)) {
        rev <- "0";
    }
    vesheim (i < louwo(line)) {
        sheye d <- line[i];
        sum <- sum + (odresdra(d) - odresdra("0"));
        wesosa (d <> "0") {
            rev <- rev + d;
        } oli wesosa (louwo(rev) > 0) {
            rev <- rev + d;
        }
        i <- i + 1;
    }
    wesosa (louwo(rev) = 0) {
        rev <- "0";
    }
    wami sum + " " + sign + odresdra(rev);
    line <- diwela();
}
"}

{"path":"solutions/t1-floordiv.res","content":"sheye line <- diwela();
veshim (line <> malwe) {
    sheye pos <- 0;
    vesheim (line[pos] <> " ") {
        pos <- pos + 1;
    }
    sheye a <- odresdra(line[0, pos - 0]);
    sheye b <- odresdra(line[pos + 1, louwo(line) - pos - 1]);
    sheye q <- a / b;
    sheye r <- a - b * q;
    wami q + " " + r;
    line <- diwela();
}
"}

{"path":"solutions/t1-palindromes.res","content":"tosedo lower(c)
    wesosa ((c >= "A") dilisyo (c <= "Z")) {
        cha ramou((odresdra(c) - odresdra("A")) + odresdra("a"));
    }
    cha c;
bawoum tosedo

sheye line <- diwela();
veshim (line <> malwe) {
    sheye chars <- [];
    sho (sheye i <- 0; i < louwo(line); i <- i + 1) {
        sheye c <- line[i];
        wesosa (((c >= "a") dilisyo (c <= "z")) emsoulve ((c >= "A") dilisyo (c <= "Z"))) {
            omse(chars, lower(c));
        } oli wesosa ((c >= "0") dilisyo (c <= "9")) {
            omse(chars, c);
        }
    }
    sheye lo <- 0;
    sheye hi <- louwo(chars) - 1;
    sheye ok <- shilsa;
    veshim (lo < hi) {
        wesosa (chars[lo] <> chars[hi]) {
