        hi <- hi - 1;
    }
    wesosa (ok) {
        wami "yes";
    } oli {
        wami "no";
    }
    line <- diwela();
}
"}

{"path":"solutions/t1-rank.res","content":"tosedo countLess(xs, x)
    sheye lo <- 0;
    sheye hi <- louwo(xs);
