        sheye mid <- (lo + hi) / 2;
        wesosa (xs[mid] < x) {
            lo <- mid + 1;
        } oli {
            hi <- mid;
        }
    }
    wesosa (lo < louwo(xs)) {
        wesosa (xs[lo] = x) {
            cha lo;
        }
    }
    cha -1;
bawoum tosedo

sheye first <- diwela();
sheye nums <- [];
wesosa (first <> malwe) {
    sho (sheye i <- 0; i < louwo(first); i <- i + 1) {
        wesosa (first[i] <> " ") {
            sheye j <- i;
            veshim ((j < louwo(first)) dilisyo (first[j] <> " ")) {
                j <- j + 1;
            }
            omse(nums, odresdra(first[i, j - i]));
            i <- j - 1;
        }
    }
}
sheye line <- diwela();
veshim (line <> malwe) {
    sheye x <- odresdra(line);
    sheye cnt <- countLess(nums, x);
