function.arguments:
{"path":"solutions/t2-bignum.res","content":"tosedo toDigits(n)
    sheye ds <- [];
    wesosa (n = 0) {
        omse(ds, 0);
        cha ds;
    }
    veshim (n > 0) {
        omse(ds, n drossou 10);
        n <- n / 10;
    }
    sheye m <- louwo(ds);
    sheye out <- [];
    sho (sheye i <- 1; i <= m; i <- i + 1) {
        omse(out, ds[m - i]);
    }
    cha out;
bawoum tosedo

tosedo toNum(ds)
    sheye n <- 0;
    sho (sheye i <- 0; i < louwo(ds); i <- i + 1) {
        n <- n * 10 + ds[i];
    }
    cha n;
bawoum tosedo

tosedo addNums(a, b)
    sheye i <- louwo(a) - 1;
    sheye j <- louwo(b) - 1;
    sheye carry <- 0;
    sheye out <- [];
    mele {
        sheye s <- carry;
        wesosa (i >= 0) {
            s <- s + a[i];
            i <- i - 1;
        }
        wesosa (j >= 0) {
            s <- s + b[j];
            j <- j - 1;
        }
        omse(out, s drossou 10);
        carry <- s / 10;
    } veshim ((i >= 0) emsoulve (j >= 0) emsoulve (carry > 0));
    sheye m <- louwo(out);
    sheye res <- [];
    sho (sheye k <- 1; k <= m; k <- k + 1) {
        omse(res, out[m - k]);
    }
    cha res;
bawoum tosedo

tosedo mulNums(a, b)
    sheye res <- [0];
    sheye m <- louwo(b);
    sho (sheye bi <- m - 1; bi >= 0; bi <- bi - 1) {
        sheye carry <- 0;
        sheye cur <- [];
        sho (sheye z <- 0; z < m - 1 - bi; z <- z + 1) {
            omse(cur, 0);
        }
        sho (sheye ai <- louwo(a) - 1; ai >= 0; ai <- ai - 1) {
            sheye p <- a[ai] * b[bi] + carry;
            omse(cur, p drossou 10);
            carry <- p / 10;
        }
        wesosa (carry > 0) {
            omse(cur, carry);
        }
        sheye mm <- louwo(cur);
        sheye rev <- [];
        sho (sheye k <- 1; k <= mm; k <- k + 1) {
            omse(rev, cur[mm - k]);
        }
        res <- addNums(res, rev);
    }
    cha res;
bawoum tosedo

tosedo trim(ds)
    sheye i <- 0;
    veshim ((i < louwo(ds)) dilisyo (ds[i] = 0)) {
        i <- i + 1;
    }
    wesosa (i = louwo(ds)) {
        sheye z <- [0];
        cha z;
    }
    cha ds[i, louwo(ds) - i];
bawoum tosedo

tosedo strOf(ds)
    sheye s <- "";
    sho (sheye i <- 0; i < louwo(ds); i <- i + 1) {
        s <- s + ramou(ds[i]);
    }
    cha s;
bawoum tosedo

sheye line <- diwela();
veshim (line <> malwe) {
    sheye pos <- 0;
    vesheim (line[pos] <> " ") {
        pos <- pos + 1;
    }
    sheye da <- toDigits(odresdra(line[0, pos]));
    sheye db <- toDigits(odresdra(line[pos + 1, louwo(line) - pos - 1]));
    wami strOf(trim(addNums(da, db))) + " " + strOf(trim(mulNums(da, db)));
    line <- diwela();
}
"}

{"path":"solutions/t2-life.res","content":"tosedo readGrid(lines)
    sheye g <- [];
    sho (sheye r <- 0; r < louwo(lines); r <- r + 1) {
        sheye row <- [];
        sho (sheye c <- 0; c < louwo(lines[r]); c <- c + 1) {
            wesosa (lines[r][c] = "#") {
                omse(row, 1);
            } oli {
                omse(row, 0);
            }
        }
        omse(g, row);
    }
    cha g;
bawoum tosedo

tosedo step(g)
    sheye rows <- louwo(g);
    sheye cols <- louwo(g[0]);
    sheye ng <- [];
    sho (sheye r <- 0; r < rows; r <- r + 1) {
        sheye row <- [];
        sho (sheye c <- 0; c < cols; c <- c + 1) {
            sheye nb <- 0;
            sho (sheye dr <- -1; dr <= 1; dr <- dr + 1) {
                sho (sheye dc <- -1; dc <= 1; dc <- dc + 1) {
                    wesosa ((dr <> 0) emsoulve (dc <> 0)) {
                        sheye rr <- r + dr;
                        sheye cc <- c + dc;
                        wesosa ((rr >= 0) dilisyo (rr < rows) dilisyo (cc >= 0) dilisyo (cc < cols)) {
                            nb <- nb + g[rr][cc];
                        }
                    }
                }
            }
            wesosa (g[r][c] = 1) {
                wesosa ((nb = 2) emsoulve (nb = 3)) {
                    omse(row, 1);
                } oli {
                    omse(row, 0);
                }
            } oli {
                wesosa (nb = 3) {
                    omse(row, 1);
                } oli {
                    omse(row, 0);
                }
            }
        }
        omse(ng, row);
    }
    cha ng;
bawoum tosedo

tosedo printGrid(g)
    sho (sheye r <- 0; r < louwo(g); r <- r + 1) {
        sheye s <- "";
        sho (sheye c <- 0; c < louwo(g[r]); c <- c + 1) {
            wesosa (g[r][c] = 1) {
                s <- s + "#";
            } oli {
                s <- s + ".";
            }
        }
        wami s;
    }
bawoum tosedo

sheye g <- odresdra(diwela());
sheye lines <- [];
sheye line <- diwela();
veshim (line <> malwe) {
    omse(lines, line);
    line <- diwela();
}
sheye grid <- readGrid(lines);
sho (sheye i <- 0; i < g; i <- i + 1) {
    grid <- step(grid);
}
printGrid(grid);
"}

{"path":"solutions/t2-rpn.res","content":"tosedo isDigit(c)
    cha (c >= "0") dilisyo (c <= "9");
